    if (scwin.isStatusUpdate) {
        $c.lc.fn_alertMsg('S1');
    } else {
        $c.lc.fn_alertMsg('S');
    }
    scwin.parentRefresh();
    if (scwin.TR_JOB === "D") {
        $c.frame.CloseFrame();
    } else {
        scwin.fn_commList();
        scwin.fn_fileList();
        buttonSet.setUpdateStatus();
