/**
 * @method
 * @name scwin.searchCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchCode = async function () {
    /* sdd-asis-lifecycle:begin fn_searchCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const arrCid = [{ cid: "ONECOM_APPL_RSN_CD", cnm: "cmb_ONECOM_APPL_RSN_CD" }, { cid: "SKIL_VALU_PROG_STAT_CD", cnm: "cmb_SKIL_VALU_PROG_STAT_CD" }, { cid: "SKIL_VALU_GRD_CD", cnm: "cmb_SKIL_VALU_GRD_CD1" }, { cid: "SKIL_VALU_GRD_CD", cnm: "cmb_SKIL_VALU_GRD_CD2" }, { cid: "SPECY_VALU_IND_CLSS_CD", cnm: "cmb_SPECY_VALU_IND_CLSS_CD" }, { cid: "SPECY_VALU_IND_CLSS_CD", cnm: "cmb_SPECY_VALU_IND_CLSS_CD2" }, { cid: "SPECY_VALU_SKIL_CLSS_CD", cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD" }, { cid: "SPECY_VALU_SKIL_CLSS_CD", cnm: "cmb_SPECY_VALU_SKIL_CLSS_CD2" }];
    let objCod;
    const url = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='ONECOM_APPL_RSN_CD','SKIL_VALU_PROG_STAT_CD','SPECY_VALU_INST_CD','SKIL_VALU_GRD_CD', 'SPECY_VALU_IND_CLSS_CD', 'SPECY_VALU_SKIL_CLSS_CD'";

    await scwin.tx_script_dts_Cod();
    let strCbd = "", i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = $c.util.getComponent(arrCid[i].cnm);
        if (objCod == null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^ ";
        if (i == 0) {
            strCbd = "^직접입력";
        }
        for (j = 1; j <= scwin.dts_Cod.CountRow; j++) {
            if (scwin.dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                const cmbValue = scwin.dts_Cod.getCellData(j, "VALUE");
                const cmbText = scwin.dts_Cod.getCellData(j, "TEXT");
                strCbd = strCbd + (strCbd === "" ? "" : ",") + cmbValue + "^" + cmbText;
            }
        }
        if(objCod)objCod.CBData=strCbd;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkForm = async function () {
    /* sdd-asis-lifecycle:begin fn_CheckForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const comNm = $c.str.trim($c.fil.getObjectValue(ipt_txb_COM_NM));
    const coreValuObjNm = $c.str.trim($c.fil.getObjectValue(ipt_txb_CORE_VALU_OBJ_NM));
    const assgnApplDd = $c.fil.getObjectValue(cal_edt_ASSGN_APPL_DD);
    if (comNm === "") {
        await $c.win.alert("회사명은 필수로 입력하여야 합니다");
        $c.util.getComponent("ipt_txb_COM_NM").focus();
        return false;
    }
    if (assgnApplDd === "") {
        await $c.win.alert("배정신청일은 필수로 입력하여야 합니다");
        $c.util.getComponent("cal_edt_ASSGN_APPL_DD").focus();
        return false;
    }
    if (!await scwin.dateCheck(cal_edt_SKIL_VALU_ASSGN_DD, "배정일")) {
        return false;
    }
    const valuInstApplCnt = $c.fil.getObjectValue(rd_rdo_VALU_INST_APPL_CNT);
    const oneComApplRsnCd = $c.fil.getObjectValue(slc_cmb_ONECOM_APPL_RSN_CD);
    const oneComApplRsnNm = $c.fil.getObjectValue(ipt_txb_ONECOM_APPL_RSN_NM);
    const valuStrtDd = $c.fil.getObjectValue(cal_edt_VALU_STRT_DD);
    const valuStrtDd2 = $c.fil.getObjectValue(cal_edt_VALU_STRT_DD2);
    const skilValuInstCd1 = $c.fil.getObjectValue(slc_cmb_SKIL_VALU_INST_CD1);
    const skilValuInstNm1 = $c.str.trim($c.fil.getObjectValue(ipt_txb_SKIL_VALU_INST_NM1));
    if (valuStrtDd !== "") {
