/**
 * @method
 * @name scwin.checkGrid
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkGrid = async function () {
    /* sdd-asis-lifecycle:begin fn_checkGrid — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let comCd, compCdIn;
    for (var i = 1, j = scwin.dts_LeadCom.CountRow; i <= j; i++) {
        comCd = scwin.dts_LeadCom.getCellData(i, "LEADCOM_MBR_NO");
        if (comCd === "") {
            await $c.win.alert("주관사에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (var k = 1, l = scwin.dts_LeadCom.CountRow; k <= l; k++) {
            if (i === k) {
                continue;
            }
            compCdIn = scwin.dts_LeadCom.getCellData(k, "LEADCOM_MBR_NO");
            if (comCd === compCdIn) {
                await $c.win.alert("동일한 주관사는 입력할 수 없습니다.");
                return false;
            }
        }
    }
    for (var i = 1, j = scwin.dts_ExecInstList.CountRow; i <= j; i++) {
        comCd = scwin.dts_ExecInstList.getCellData(i, "SPECY_VALU_INST_CD");
        if (comCd === "") {
            await $c.win.alert("제척기관에 빈값을 선택할수 없스니다.");
            return false;
        }
        for (var k = 1, l = scwin.dts_ExecInstList.CountRow; k <= l; k++) {
            if (i === k) {
                continue;
            }
            compCdIn = scwin.dts_ExecInstList.getCellData(k, "SPECY_VALU_INST_CD");
            if (comCd === compCdIn) {
                await $c.win.alert("동일한 제척기관은 입력할 수 없습니다.");
                return false;
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


