    const applCnt = $c.fil.getObjectValue(rd_rdo_VALU_INST_APPL_CNT);
    const valueYn = $c.fil.getObjectValue(slc_cmb_ONECOM_APPL_RSN_CD);
    if (valueYn === "99" && applCnt === "1") {
        await $c.win.alert("특례대상여부가 해당없음인 경우 1사 선택 불가");
        $c.fil.setObjectValue(rd_rdo_VALU_INST_APPL_CNT, "2");
        rd_rdo_VALU_INST_APPL_CNT.removeAll();
        return;
    }
    if (applCnt === "1") {
        slc_cmb_SKIL_VALU_INST_CD2.enable2 = false;
        slc_cmb_SKIL_VALU_GRD_CD2.enable2 = false;
        $c.util.getComponent('cal_edt_VALU_RSLT_DD2').setDisabled(!(false));
        $c.fil.setObjectValue(slc_cmb_SKIL_VALU_INST_CD2, "");
        $c.fil.setObjectValue(ipt_txb_SKIL_VALU_INST_NM2, "");
        $c.fil.setObjectValue(slc_cmb_SKIL_VALU_GRD_CD2, "");
        $c.fil.setObjectValue(cal_edt_VALU_RSLT_DD2, "");
        $c.util.getComponent('ipt_txb_SKIL_VALU_INST_NM2').setDisabled(true);
    } else {
        slc_cmb_SKIL_VALU_INST_CD2.enable2 = true;
        $c.util.getComponent('ipt_txb_SKIL_VALU_INST_NM2').setDisabled(false);
        slc_cmb_SKIL_VALU_GRD_CD2.enable2 = true;
        $c.util.getComponent('cal_edt_VALU_RSLT_DD2').setDisabled(!(true));
    }
    /* sdd-asis-lifecycle:end */
};


