/**
 * @method
 * @name scwin.checkFileNameSize
 * @author Inswave
 * @date 2026. 09. 29
 * @param fileName
 * @returns
 * @hidden N
*/
scwin.checkFileNameSize = async function (fileName) {
    /* sdd-asis-lifecycle:begin checkFileNameSize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const nameByte = $c.str.getByteLength(fileName);
