*/
scwin.fileDelete = async function (fileDiv) {
    /* sdd-asis-lifecycle:begin fn_fileDelete — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let txtFileObj, fileRow;
    txtFileObj = eval("txb_FILE_NM" + fileDiv);
    if (txtFileObj.value === "") {
        return;
    } else {
        if (await $c.win.confirm("파일을 삭제하시겠습니까?")) {
            txtFileObj.value = "";
            fileRow = scwin.dts_fileInfo.NameValueRow("FILE_DIV", scwin.fileTpCdarr[fileDiv - 1]);
            if (fileRow > 0) {
                scwin.dts_fileInfo.removeRow(fileRow);
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


